import json

# Python script to compile 200 structured Matura books
books = []

# Helper to add book
def add_b(id, title, author, isbn, period, genre, time_place, theme, chars, plot, style, ebook="", audio=""):
    books.append({
        "id": id,
        "title": title,
        "author": author,
        "isbn": isbn,
        "period": period,
        "genre": genre,
        "timeAndPlace": time_place,
        "themeAndMotifs": theme,
        "characters": chars,
        "plotSummary": plot,
        "languageAndStyle": style,
        "ebookUrl": ebook,
        "audiobookUrl": audio
    })

